vec4 convertFromLinear(vec4 val, int clip)
{
    // "Encoding Function" per 20220501_LogC_Specification.pdf
    const float a = (pow(2.0,18.0) - 16.0) / 117.45;
    const float b = (1023.0 - 95.0) / 1023.0;
    const float b14 = b / 14.0;
    const float c = 95.0 / 1023.0;
    const float s = (7.0 * log(2.0) * pow(2.0, 7.0 - 14.0 * c / b)) / (a * b);
    const float t = (pow(2.0,-c/b14+6.0) - 64.0) / a;

    vec3 q = a * val.rgb + 64.0;

    return vec4
    (
	(val.r >= t) ? (log2(q.r) - 6.0) * b14 + c : (val.r - t) / s,
	(val.g >= t) ? (log2(q.g) - 6.0) * b14 + c : (val.g - t) / s,
	(val.b >= t) ? (log2(q.b) - 6.0) * b14 + c : (val.b - t) / s,
	val.a
    );
}

