vec4 convertFromLinear(vec4 val, int clip)
{
    float Lw = 1000.0;  // white nits
    float Lb = 0.0;    // black nits
    float gamma = 1.2;
    float alpha = Lw - Lb;
    float beta = Lb;    
    float delta = beta*(0.2627 + 0.6780 + 0.0593);    
    vec3 P = abs(val.rgb) * vec3(Lw);
    float Y = pow(max(0.000001,(0.2627*P.r + 0.6780*P.g + 0.0593*P.b - delta)/alpha), 1.0/gamma - 1.0);
    P = (P - vec3(beta))*vec3(Y/alpha);
    P.r = P.r < (1.0/12.0) ? sqrt(3.0*P.r) : (0.17883277*log(P.r-0.02372241) + 1.00429347);
    P.g = P.g < (1.0/12.0) ? sqrt(3.0*P.g) : (0.17883277*log(P.g-0.02372241) + 1.00429347);
    P.b = P.b < (1.0/12.0) ? sqrt(3.0*P.b) : (0.17883277*log(P.b-0.02372241) + 1.00429347);
    return vec4(sign(val.rgb)*P, val.a);
}

