    float alpha = Lw - Lb;
    float beta = Lb;
    vec3 P = min(abs(val.rgb), 13.0);
    P.r = P.r < 0.5 ? P.r*P.r/3.0 : exp((P.r-1.00429347)/0.17883277) + 0.02372241;
    P.g = P.g < 0.5 ? P.g*P.g/3.0 : exp((P.g-1.00429347)/0.17883277) + 0.02372241;
    P.b = P.b < 0.5 ? P.b*P.b/3.0 : exp((P.b-1.00429347)/0.17883277) + 0.02372241;
    float Ys = max(0.0, 0.2627*P.r + 0.6780*P.g + 0.0593*P.b);
