    val.r = val.r < 0.0 ? G*val.r + o : log(val.r + C)*B + A; 
    val.g = val.g < 0.0 ? G*val.g + o : log(val.g + C)*B + A; 
    val.b = val.b < 0.0 ? G*val.b + o : log(val.b + C)*B + A; 

    return val;
}

